using ll = long long;

int main() {
    int t;
    cin>>t;
    while(t--){
        int n;
        cin>>n;
        vector<int> v(3*n);
        for(auto &e:v)cin>>e;
        sort(v.rbegin(),v.rend());
        vector<ll> pre(1,0);
        for(auto &e:v) pre.push_back(e+pre.back());
        ll ans = 0;
        for(ll a=0;a<=n;a++){
            ll sum = 6*pre[a];
            ll i = a;
            ll j = (3*n-3*a)+i-1;
            ll start = 0, end = (n-a);
            while(end-start>1){
                ll mid = (end+start)/2;
                if((v[i+mid*2-1]+v[i+mid*2-2])-3*(v[j-mid+1])>=0){
                    start = mid;
                }else end = mid-1;
            }
            if(end>start && v[i+end*2-1]+v[i+end*2-2]-3*v[j-end+1]>=0){
                start = end;
            }
            ll b = start;
            ll c = n-a-b;
            // cerr<<6*(pre[a])+(pre[a+b*2]-pre[a])*4+(pre[a+b*2+c*3]-pre[a+b*2])*3<<" "<<a<<" "<<b<<" "<<c<<endl;
            ans = max(ans,6*(pre[a])+(pre[a+b*2]-pre[a])*4+(pre[a+b*2+c*3]-pre[a+b*2])*3);
        }
        cout<<ans<<endl;
